const listDispatchableJobs = `-- name: ListDispatchableJobs :many
SELECT j.id, j.org_id, j.deployment_id, j.device_id, j.user_sid, j.type, j.title, j.body, j.depends_on, j.not_before, j.expires_at, j.attempt, j.status, j.status_reason, j.envelope, j.created_at, j.sent_at, j.acked_at, j.started_at, j.finished_at, j.exit_code, j.detection_passed, j.reboot_required, j.cancel_pending, j.result, j.depends_when, j.script_run_id FROM jobs j
WHERE j.device_id = $1 AND j.status IN ('queued', 'sent') AND j.expires_at > now()
  AND (j.depends_on IS NULL OR EXISTS (SELECT 1 FROM jobs p WHERE p.id = j.depends_on AND (
        p.status IN ('succeeded', 'succeeded_reboot')
        OR (j.depends_when = 'finished' AND p.status IN ('failed', 'expired', 'rejected')))))
ORDER BY j.not_before, j.created_at, j.id
`

// Jobs the device should hold: not yet acknowledged, still valid, dependencies satisfied.
func (q *Queries) ListDispatchableJobs(ctx context.Context, deviceID uuid.UUID) ([]Job, error) {
	rows, err := q.db.Query(ctx, listDispatchableJobs, deviceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Job{}
	for rows.Next() {
		var i Job
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.DeploymentID,
			&i.DeviceID,
			&i.UserSid,
			&i.Type,
			&i.Title,
			&i.Body,
			&i.DependsOn,
			&i.NotBefore,
			&i.ExpiresAt,
			&i.Attempt,
			&i.Status,
			&i.StatusReason,
			&i.Envelope,
			&i.CreatedAt,
			&i.SentAt,
			&i.AckedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.ExitCode,
			&i.DetectionPassed,
			&i.RebootRequired,
			&i.CancelPending,
			&i.Result,
			&i.DependsWhen,
			&i.ScriptRunID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

